import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)
    try:
        N = int(next(iterator))
        K = int(next(iterator))
        A = []
        for _ in range(N):
            A.append(int(next(iterator)))
    except StopIteration:
        return

    if N <= 2:
        start = -float('inf')
        diff = -float('inf')
        best_start = None
        best_diff = None

        if N == 1:
            best_start = A[0]
            best_diff = 0
        else:
            best_start = A[0]
            best_diff = A[1] - A[0]

        if best_start is not None:
            res = [best_start + i * best_diff for i in range(N)]
            print(" ".join(map(str, res)))
        return

    candidates = set()

    if K >= 2:
        candidates.add((A[0], A[1] - A[0]))

    for i in range(N):
        for j in range(i + 1, N):
            dist = j - i
            num_diff = A[j] - A[i]
            if num_diff % dist == 0:
                d = num_diff // dist
                a0 = A[i] - i * d
                candidates.add((a0, d))

    if not candidates:
        candidates.add((A[0], A[1] - (A[0] if N > 1 else 0)))

    best_a0 = None
    best_d = None

    for a0, d in candidates:
        changes = 0
        for i in range(N):
            expected = a0 + i * d
            if A[i] != expected:
                changes += 1
        if changes <= K:
            if best_a0 is None:
                best_a0 = a0
                best_d = d
            else:
                if a0 < best_a0 or (a0 == best_a0 and d < best_d):
                    best_a0 = a0
                    best_d = d

    if best_a0 is None:
        if N >= 2:
            best_a0 = A[0]
            best_d = A[1] - A[0]
        else:
            best_a0 = A[0]
            best_d=0

    result = [best_a0 + i * best_d for i in range(N)]
    print(" ".join(map(str, result)))

if __name__ == "__main__":
    solve()
